# 创建
def __init__(self):
    self.table = [None] * 12

# 模数哈希函数
def H(self, key):
    # 等于键对哈希表大小求余
    return key % 12

# 显示表
def display(self):
    for hash_value, key in enumerate(self.table):
        print(f'{hash_value}:{key}')

def insert(self, value):
    key = self.H(value)
    if self.table[key] is None:
        self.table[key] = [value]
    else:
        self.table[key].append(value)
        self.table[key] = sorted(self.table[key])

def retrieve(self, value):
    # 查找该值的相应链表
    key = self.H(value)
    value_list = self.table[key]
    # 遍历链表以查找值
    if value_list is not None:
        for val in value_list:
            if val == value:
                # 返回值（如果存在）
                return val
    # 否则返回None
    return None

class ChainingHashTable:

    def __init__(self, size=12):
        self.size = size
        self.table = [None] * self.size

    def H(self, key):
        return key % self.size

    def insert(self, value):
        key = self.H(value)
        if self.table[key] is None:
            self.table[key] = [value]
        else:
            self.table[key].append(value)
            self.table[key] = sorted(self.table[key])

    def display(self):
        for key, value_list in enumerate(self.table):
            print(f'Index {key}: {value_list}')

    def retrieve(self, value):
        key = self.H(value)
        value_list = self.table[key]
        if value_list is not None:
            for val in value_list:
                if val == value:
                    return val
        return None

elements = [12, 14, 2, 6, 9, 35]
hash_table = ChainingHashTable()
for element in elements:
    hash_table.insert(element)

hash_table.display()
print(f'\nRetrieved Value: {hash_table.retrieve(14)}')

